// ── Only react to "/lyrics <title or part of the lyrics>" (also "/lyrics@YourBot ..."). Anything else stops here. ──
const BOT_TOKEN = 'PASTE_BOT_TOKEN';        // from @BotFather
const GENIUS_TOKEN = 'PASTE_GENIUS_TOKEN';  // free: genius.com/api-clients (optional, needed to search by part of the lyrics)

const u = $input.first().json;
const m = u.message || u.channel_post;
if (!m || typeof m.text !== 'string') return [];
const mt = m.text.trim().match(/^\/lyrics(?:@\w+)?(?:\s+([\s\S]*))?$/i);
if (!mt) return [];

const enc = encodeURIComponent;
const raw = (mt[1] || '').trim();
const parts = raw.split(/\s+[-–—]\s+/);
const explicit = parts.length >= 2;
const title = (explicit ? parts[0] : raw).trim();
const artist = explicit ? parts.slice(1).join(' ').trim() : '';
const plain = raw.replace(/\s+[-–—]\s+/g, ' ');

return [{
  json: {
    raw,
    explicit,
    title,
    artist,
    query: enc(raw),
    qPlain: enc(plain),
    keyword: plain.replace(/[^\w\s-]/g, '').replace(/\s+/g, '+'),
    lookupUrl: 'https://lrclib.net/api/search?track_name=' + enc(title) + (artist ? '&artist_name=' + enc(artist) : ''),
    chatId: m.chat.id,
    // reply inside the same topic (sub-channel) when the command came from one
    threadId: m.is_topic_message ? m.message_thread_id : null,
    botToken: BOT_TOKEN,
    geniusToken: GENIUS_TOKEN
  }
}];

// ── CODE 1: extractLinks(html, source) -> one item per candidate page: { source, title, artist, url } ──
const decode = (s) => s
  .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(+n))
  .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCharCode(parseInt(h, 16)))
  .replace(/&nbsp;/g, ' ').replace(/&rsquo;|&lsquo;/g, "'").replace(/&hellip;/g, '...')
  .replace(/&quot;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');

function extractLinks(body, source) {
  const out = [];
  if (source === 'Genius') {                       // Genius API (JSON): hits -> genius.com song pages
    let o; try { o = JSON.parse(body); } catch (e) { return out; }
    for (const h of ((o.response && o.response.hits) || []).filter((h) => h.type === 'song').slice(0, 4)) {
      out.push({ source, title: h.result.title, artist: (h.result.primary_artist || {}).name || '', url: h.result.url });
    }
  } else if (source === 'LRCLIB') {                // LRCLIB search (JSON): each hit has an id -> /api/get/{id}
    let o; try { o = JSON.parse(body); } catch (e) { return out; }
    for (const x of (Array.isArray(o) ? o : []).filter((x) => x && x.id && x.trackName && x.plainLyrics).slice(0, 6)) {
      out.push({ source, title: x.trackName, artist: x.artistName || '', url: 'https://lrclib.net/api/get/' + x.id });
    }
  } else if (source === 'AfricanGospel') {         // AfricanGospelLyrics search page (HTML)
    if (body.length < 300 || /cf-browser-verification|attention required|captcha|access denied|just a moment/i.test(body)) return out;
    for (const l of [...body.matchAll(/<h[1-4][^>]*class="[^"]*title[^"]*"[^>]*>\s*<a[^>]+href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/gi)].slice(0, 3)) {
      out.push({ source, title: decode(l[2].replace(/<[^>]+>/g, '')).replace(/\s+lyrics.*$/i, '').trim(), artist: '', url: l[1] });
    }
  }
  return out;
}

const all = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const body = typeof j.data === 'string' ? j.data.trim() : '';
  if (body.length < 2) continue;                   // failed / empty branch
  all.push(...extractLinks(body, j.source || ''));
}

// Nothing found anywhere: send a harmless marker so the run still reaches the "no results" reply
if (!all.length) return [{ json: { source: 'none', title: '', artist: '', url: 'https://lrclib.net/api/search?q=%20', none: true } }];
return all.map((json) => ({ json }));

// ── CODE 2: deduplicate links (same source + same title/artist, or same URL) ──
const norm = (s) => String(s || '').toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!j || !j.url) continue;
  const k1 = j.source + '|' + norm(j.title) + '|' + norm(j.artist);
  if (seen.has(k1) || seen.has(j.url)) continue;
  seen.add(k1); seen.add(j.url);
  out.push({ json: j });
}
return out.length ? out : [{ json: { source: 'none', title: '', artist: '', url: 'https://lrclib.net/api/search?q=%20', none: true } }];

// ── CODE 3: parseLyrics(html, source) -> { source, title, artist, url, lyrics, lyricsLength } ──
// The HTTP node drops title/source, so we re-attach them from "Deduplicate Links" (same order, one-to-one).
const links = $('Deduplicate Links').all();
const decode = (s) => s
  .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(+n))
  .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCharCode(parseInt(h, 16)))
  .replace(/&nbsp;/g, ' ').replace(/&rsquo;|&lsquo;/g, "'").replace(/&hellip;/g, '...')
  .replace(/&quot;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
const htmlToText = (h) => decode(h
  .replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, '')
  .replace(/<br\s*\/?>/gi, '\n').replace(/<\/p>/gi, '\n\n').replace(/<[^>]+>/g, ''));
const blocked = (h) => /cf-browser-verification|attention required|captcha|access denied|just a moment/i.test(h);

function parseLyrics(body, source) {
  if (source === 'LRCLIB') {
    try { const o = JSON.parse(body); return o.plainLyrics || ''; } catch (e) { return ''; }
  }
  if (blocked(body)) return '';
  if (source === 'Genius') {
    const parts = body.split(/data-lyrics-container="true"[^>]*>/i).slice(1);
    return parts.map((p) => htmlToText(p.split(/Lyrics__Footer|LyricsFooter|<\/main>/)[0]).trim()).filter(Boolean).join('\n\n');
  }
  if (source === 'AfricanGospel') {
    const i = body.search(/class="[^"]*entry-content/i);
    if (i < 0) return '';
    let seg = body.slice(i);
    seg = seg.slice(seg.indexOf('>') + 1).split(/<\/article>|<footer|class="[^"]*(?:sharedaddy|post-navigation|related)/i)[0];
    return htmlToText(seg).trim();
  }
  return '';
}

const out = [];
$input.all().forEach((item, i) => {
  const meta = ((links[i] || {}).json) || {};
  const j = item.json || {};
  if (meta.none || j.error) return;
  const body = typeof j.data === 'string' ? j.data : (typeof j.body === 'string' ? j.body : (j && typeof j === 'object' && j.plainLyrics ? JSON.stringify(j) : ''));
  if (!body) return;
  let lyrics = '';
  try { lyrics = parseLyrics(body, meta.source); } catch (e) { return; }
  lyrics = lyrics.replace(/\r/g, '').trim();
  if (lyrics.length < 80) return;
  out.push({ json: { source: meta.source, title: meta.title, artist: meta.artist, url: meta.url, lyrics, lyricsLength: lyrics.length } });
});
return out;   // may be empty -> "Pick Best Lyrics" still runs (Always Output Data) and sends the no-results notice

// ── CODE 4: deduplicate by title + lyrics, pick the best match -> { title, artist, lyrics, source, url } ──
const P = $('Parse Query').first().json;
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const norm = (s) => String(s || '').toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
const hasGenius = P.geniusToken && !/PASTE_|YOUR_/i.test(P.geniusToken);

const marker = (msg, error) => [{ json: {
  title: null, source: 'none', error,
  payload: { chat_id: P.chatId, ...(P.threadId ? { message_thread_id: P.threadId } : {}), text: msg, parse_mode: 'HTML', disable_web_page_preview: true }
} }];

if (!P.raw) return marker('Usage: <code>/lyrics song title or part of the lyrics</code>\nExample: <code>/lyrics Way Maker - Sinach</code>', 'empty query');

const tokens = norm(P.raw).split(' ').filter((w) => w.length > 1);
const useTokens = tokens.length ? tokens : norm(P.raw).split(' ').filter(Boolean);

// dedupe: same title + same opening of the lyrics
const seen = new Set();
const uniq = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!j || !j.lyrics) continue;
  const k = norm(j.title) + '|' + norm(j.lyrics).slice(0, 160);
  if (seen.has(k)) continue;
  seen.add(k);
  uniq.push(j);
}

let best = null;
for (const j of uniq) {
  const hay = new Set(norm(j.title + ' ' + j.artist + ' ' + j.lyrics).split(' '));
  const s = useTokens.filter((t) => hay.has(t)).length / useTokens.length;
  if (!best || s > best.s) best = { j, s };
}
if (!best || best.s < (P.explicit ? 0.3 : 0.6)) {
  let msg = 'No lyrics found for <b>' + esc(P.raw) + '</b>.\nTry: <code>/lyrics Title - Artist</code>';
  if (!hasGenius) msg += '\n\n<i>Searching by a part of the lyrics works best with a Genius API token (Parse Query node).</i>';
  return marker(msg, 'all sources blocked or empty');
}
const { title, artist, lyrics, source, url } = best.j;
return [{ json: { title, artist, lyrics, source, url } }];

