// ── AI output -> checked -> split into Telegram-sized messages. If the AI failed or changed the lyrics, format in code instead. ──
const P = $('Parse Query').first().json;
const N = $('Pick Best Lyrics').first().json;
const ai = $input.first().json || {};

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const norm = (s) => String(s || '').toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();

const clean = (t) => String(t || '')
  .replace(/\r/g, '')
  .replace(/^Paroles de la chanson.*$/gim, '')
  .replace(/^\s*\[[^\]\n]*\]\s*$/gm, '')
  .replace(/^\s*(verse|chorus|pre-?chorus|bridge|intro|outro|refrain|tag|interlude)\s*\d*\s*:?\s*$/gim, '')
  .slice(0, 20000);

// Deterministic 2-lines-per-slide formatter (safety net)
function pairUp(text) {
  const stanzas = text.split(/\n\s*\n/).map((s) => s.split('\n').map((l) => l.trim()).filter(Boolean)).filter((a) => a.length);
  const blocks = [];
  for (const st of stanzas) for (let i = 0; i < st.length; i += 2) blocks.push(st.slice(i, i + 2).join('\n'));
  return blocks;
}

const source = clean(N.lyrics);
let blocks = pairUp(source);
let usedAI = false;

// Accept the AI version only if it kept the lyrics intact
let out = typeof ai.output === 'string' ? ai.output.trim() : '';
out = out.replace(/^```[a-z]*\n?/i, '').replace(/\n?```$/, '').trim();
if (out) {
  const lines = out.split('\n');
  if (norm(lines[0]) === norm(N.title) || norm(lines[0]) === norm(N.title + ' ' + N.artist)) lines.shift();
  const body = lines.join('\n').trim();
  const srcWords = norm(source).split(' ').filter(Boolean);
  const aiWords = norm(body).split(' ').filter(Boolean);
  const srcSet = new Set(srcWords);
  const inSrc = aiWords.filter((w) => srcSet.has(w)).length;
  if (aiWords.length >= srcWords.length * 0.85 && aiWords.length <= srcWords.length * 1.15 && inSrc / aiWords.length >= 0.97) {
    const aiBlocks = body.split(/\n\s*\n/).map((b) => b.trim()).filter(Boolean);
    if (aiBlocks.length) { blocks = aiBlocks; usedAI = true; }
  }
}

const head = '<b>' + esc(N.title) + '</b>' + (N.artist ? '\n<i>' + esc(N.artist) + '</i>' : '');
const chunks = [];
let cur = head;
for (const b of blocks.map(esc)) {
  if ((cur + '\n\n' + b).length > 3800) { chunks.push(cur); cur = b; } else { cur += '\n\n' + b; }
}
chunks.push(cur);

return chunks.map((text) => ({
  json: {
    formattedBy: usedAI ? 'ai' : 'code',
    payload: { chat_id: P.chatId, ...(P.threadId ? { message_thread_id: P.threadId } : {}), text, parse_mode: 'HTML', disable_web_page_preview: true }
  }
}));
